1	package ociresources
2	
3	import (
4		"strings"
5	
6		"github.com/charmbracelet/bubbles/spinner"
7		tea "github.com/charmbracelet/bubbletea"
8	
9		"github.com/anthnel/devdesk/internal/config"
10		"github.com/anthnel/devdesk/internal/docker"
11	)
12	
13	// InEditMode returns true when a text input is active (blocks command mode).
14	func (b *RegistryBrowser) InEditMode() bool {
15		if b.state == browserStateInput && b.focusedField == brFieldRepo {
16			return true
17		}
18		return b.state == browserStateTags && b.filterActive
19	}
20	
21	// IsSearching returns true while registry tag queries are still in flight.
22	func (b *RegistryBrowser) IsSearching() bool {
23		return b.pendingSearches > 0
24	}
25	
26	// Update handles all messages for the browser.
27	func (b *RegistryBrowser) Update(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
28		switch msg := msg.(type) {
29		case tea.KeyMsg:
30			return b.handleKeyMsg(msg)
31		case spinner.TickMsg:
32			if b.state == browserStateStatus || len(b.scanningTags) > 0 || b.pendingSearches > 0 {
33				var cmd tea.Cmd
34				b.spinner, cmd = b.spinner.Update(msg)
35				if b.state == browserStateTags && len(b.scanningTags) > 0 {
36					b.tagScanSpinnerIdx++
37					b.rebuildTagTable()
38				}
39				return b, cmd
40			}
41			return b, nil
42		}
43		return b.delegateUpdate(msg)
44	}
45	
46	func (b *RegistryBrowser) delegateUpdate(msg tea.Msg) (*RegistryBrowser, tea.Cmd) {
47		if b.state == browserStateInput && b.focusedField == brFieldRepo {
48			var cmd tea.Cmd
49			b.repoInput, cmd = b.repoInput.Update(msg)
50			return b, cmd
51		}
52		if b.state == browserStateTags {
53			if b.filterActive {
54				var cmd tea.Cmd
55				b.filterInput, cmd = b.filterInput.Update(msg)
56				b.rebuildTagTable()
57				return b, cmd
58			}
59			var cmd tea.Cmd
60			b.tagTable, cmd = b.tagTable.Update(msg)
61			return b, cmd
62		}
63		return b, nil
64	}
65	
66	func (b *RegistryBrowser) handleKeyMsg(msg tea.KeyMsg) (*RegistryBrowser, tea.Cmd) {
67		switch b.state {
68		case browserStateInput:
69			return b.handleInputKeyMsg(msg)
70		case browserStateTags:
71			return b.handleTagsKeyMsg(msg)
72		case browserStateStatus:
73			return b, nil
74		}
75		return b, nil
76	}
77	
78	func (b *RegistryBrowser) handleInputKeyMsg(msg tea.KeyMsg) (*RegistryBrowser, tea.Cmd) {
79		switch msg.String() {
80		case "esc":
81			return b, func() tea.Msg { return RegistryBrowserCloseMsg{} }
82		case "down":
83			b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
84			b.updateFocus()
85			return b, nil
86		case "up":
87			b.focusedField = max(b.focusedField-1, brFieldRepo)
88			b.updateFocus()
89			return b, nil
90		case " ":
91			if b.focusedField >= 1 && b.focusedField <= len(b.rows) {
92				row := b.rows[b.focusedField-1]
93				if row.groupSlug != "" {
94					b.toggleGroup(row.groupSlug)
95					return b, nil
96				}
97				url := b.entries[row.entry].URL
98				b.selectedRegs[url] = !b.selectedRegs[url]
99				return b, nil
100			}
101		case "enter":
102			if b.focusedField == brFieldRepo || b.focusedField == b.brFieldSubmit() {
103				return b.submitSearch()
104			}
105			b.focusedField = min(b.focusedField+1, b.brFieldSubmit())
106			b.updateFocus()
107			return b, nil
108		}
109		return b.delegateUpdate(msg)
110	}
111	
112	// credsFor returns the credentials to search entry with, and nothing at all
113	// when the registry — or the group it belongs to — is marked anonymous (D12).
114	// Docker keys credentials by host, so a Nexus instance with one repository
115	// logged into would otherwise send that login to every repository it serves.
116	func (b *RegistryBrowser) credsFor(entry browserRegistryEntry) (string, string) {
117		if !config.UsesCredentials(entry.authMode) {
118			return "", ""
119		}
120		// Credentials come from the parent registry, or the entry itself for a
121		// registry that is not a group member.
122		credURL := entry.URL
123		if entry.parentURL != "" {
124			credURL = entry.parentURL
125		}
126		var username string
127		for _, reg := range b.registries {
128			if reg.URL == credURL {
129				username = reg.Username
130				break
131			}
132		}
133		storedUser, storedPass, _ := docker.GetStoredCreds(credURL)
134		if username == "" {
135			username = storedUser
136		}
137		return username, storedPass
138	}
139	
140	func (b *RegistryBrowser) submitSearch() (*RegistryBrowser, tea.Cmd) {
141		repo := strings.TrimSpace(b.repoInput.Value())
142		if repo == "" {
143			return b, nil
144		}
145	
146		b.tags = nil
147		b.registryFilter = resultFilter{}
148		b.pendingSearches = 0
149		b.filterInput.SetValue("")
150		b.filterActive = false
151		b.tagSortCol = tagSortByName
152		b.tagSortDesc = false
153	
154		var cmds []tea.Cmd
155		for _, entry := range b.entries {
156			if !b.selectedRegs[entry.URL] {
157				continue
158			}
159			username, storedPass := b.credsFor(entry)
160			alias := entry.Alias
161			if entry.ParentAlias != "" {
162				alias = entry.ParentAlias + "/" + entry.Alias
163			}
