124	// includes memberNames: GET /v1/repositories/{format}/group/{name}
125	// Requires nx-repository-admin privilege; falls back to anonymous when credentials fail.
126	func (n *NexusDetector) fetchGroupMembers(ctx context.Context, host, repoName, format string, info RegistryInfo) []GroupMember {
127		if format == "" {
