129		}
130		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s/group/%s", host, format, repoName)
131		body, err := n.nexusGET(ctx, endpoint, info)
132		if err != nil {
133			// When auth is present but the request fails, retry anonymously.
134			// Some Nexus instances allow anonymous read of the group admin endpoint.
135			if info.Username != "" && info.Password != "" {
136				anonInfo := RegistryInfo{URL: info.URL, ManagementURL: info.ManagementURL}
137				body, err = n.nexusGET(ctx, endpoint, anonInfo)
138			}
139		}
140		if err != nil {
141			log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — account may lack nx-repository-admin privilege; run 'docker login %s' with an admin account", endpoint, err, host)
142			return nil
143		}
144		var result struct {
145			Group struct {
146				MemberNames []string `json:"memberNames"`
147			} `json:"group"`
148		}
149		if err := json.Unmarshal(body, &result); err != nil {
150			return nil
151		}
152		members := make([]GroupMember, 0, len(result.Group.MemberNames))
153		for _, name := range result.Group.MemberNames {
154			members = append(members, GroupMember{
155				Alias: cleanMemberAlias(name),
156				URL:   fmt.Sprintf("%s/repository/%s", host, name),
157			})
158		}
159		return members
160	}
