162	// nexusGET performs an authenticated GET and returns the response body.
163	func (n *NexusDetector) nexusGET(ctx context.Context, endpoint string, info RegistryInfo) ([]byte, error) {
164		req, err := http.NewRequestWithContext(ctx, "GET", endpoint, nil)
165		if err != nil {
166			return nil, err
167		}
168		if info.Username != "" && info.Password != "" {
169			req.SetBasicAuth(info.Username, info.Password)
170		}
171		resp, err := nexusHTTPClient.Do(req)
172		if err != nil {
173			return nil, err
174		}
175		defer func() { _ = resp.Body.Close() }()
176		if resp.StatusCode != http.StatusOK {
177			return nil, fmt.Errorf("HTTP %d", resp.StatusCode)
178		}
179		var buf []byte
180		buf, err = io.ReadAll(resp.Body)
181		return buf, err
182	}
183	
184	// parseNexusURL extracts the scheme+host and repository name from a Nexus URL.
185	// e.g. "https://nexus.example.com/repository/docker-group" → ("https://nexus.example.com", "docker-group")
186	func parseNexusURL(registryURL string) (host, repoName string, err error) {
187		raw := registryURL
188		if !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
189			raw = "https://" + raw
190		}
191		u, err := url.Parse(raw)
192		if err != nil {
193			return "", "", err
194		}
195		parts := strings.SplitN(strings.TrimPrefix(u.Path, "/"), "/", 3)
196		// Expected: ["repository", "<repoName>", ...]
197		if len(parts) < 2 || parts[0] != "repository" || parts[1] == "" {
198			return "", "", fmt.Errorf("not a Nexus repository path: %q", u.Path)
199		}
200		host = u.Scheme + "://" + u.Host
201		repoName = parts[1]
202		return host, repoName, nil
203	}
204	
205	// cleanMemberAlias strips common suffixes (-proxy, -hosted, -local) for a friendlier display name.
206	func cleanMemberAlias(name string) string {
207		for _, suffix := range []string{"-proxy", "-hosted", "-local"} {
208			if strings.HasSuffix(name, suffix) {
209				return name[:len(name)-len(suffix)]
210			}
211		}
212		return name
213	}
