1	package ociresources
2	
3	import (
4		"sort"
5		"strings"
6	
7		tea "github.com/charmbracelet/bubbletea"
8	)
9	
10	func (b *RegistryBrowser) cycleSortTags() {
11		if b.tagSortCol == tagSortByName && !b.tagSortDesc {
12			b.tagSortDesc = true
13		} else if b.tagSortCol == tagSortByName && b.tagSortDesc {
14			b.tagSortCol = tagSortByUpdated
15			b.tagSortDesc = false
16		} else if b.tagSortCol == tagSortByUpdated && !b.tagSortDesc {
17			b.tagSortDesc = true
18		} else {
19			b.tagSortCol = tagSortByName
20			b.tagSortDesc = false
21		}
22		b.rebuildTagTable()
23	}
24	
25	// filterStops returns the values `r` cycles through: every group that produced
26	// results, then every individual registry, then off. The group level is what
27	// makes "everything from this Nexus" one keystroke rather than eight.
28	func (b *RegistryBrowser) filterStops() []resultFilter {
